/*
 * Dedup against the library as it actually is, rather than against a list
 * assembled while generating this file. Four names slipped through that way —
 * the earlier pass read the seed with a regular expression and missed the rows
 * whose insert is shaped differently.
 */
where not exists (
  select 1 from services e
  where e.company_id is null
    and lower(btrim(e.name)) = lower(btrim(v.name)))
on conflict do nothing;
